const patterns = ["node_modules/", ".env", "*.log"];

function isIgnored(path, patterns) {
  const name = path.split("/").at(-1);
  return patterns.some((p) => {
    if (p.endsWith("/")) return path.startsWith(p) || path.includes("/" + p);
    if (p.startsWith("*")) return path.endsWith(p.slice(1));
    return name === p;
  });
}

for (const path of ["node_modules/pg/index.js", ".env", "config/.env", "logs/app.log", ".env.example", "server.js"]) {
  console.log(path, isIgnored(path, patterns));
}

