const VAGUE = ["stuff", "fix", "wip", "changes"];

function checkMessage(message) {
  const text = message.trim();
  if (text === "") return ["empty"];
  const problems = [];
  if (VAGUE.includes(text.toLowerCase())) problems.push("too vague");
  if (text.length > 50) problems.push("too long");
  if (/^[a-z]/.test(text)) problems.push("start with a capital");
  return problems;
}

console.log(checkMessage("Read the port from PORT"));
console.log(checkMessage("fix"));
console.log(checkMessage("   "));
console.log(checkMessage("add a very long message that explains far too much in one line"));

