function markerLines(text) {
  const markers = ["<<<<<<<", "=======", ">>>>>>>"];
  const found = [];
  text.split("\n").forEach((line, i) => {
    if (markers.some((m) => line.startsWith(m))) found.push(i + 1);
  });
  return found;
}

