function toExample(text) {
  return text
    .split("\n")
    .map((line) => {
      if (line.trim() === "" || line.startsWith("#")) return line;
      return line.slice(0, line.indexOf("=") + 1);
    })
    .join("\n");
}

const env = "# database\nDATABASE_URL=postgres://postgres:hunter2@localhost:5434/taskdb\n\nPORT=3000";
console.log(toExample(env));

